import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PIN_A = 20
PIN_B = 21
POLL_INTERVAL = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    pin_a = None
    pin_b = None
    try:
        pin_a = OutputDevice(PIN_A)
        pin_b = OutputDevice(PIN_B)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO pins {PIN_A}/{PIN_B}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                state_a = pin_a.value
                state_b = pin_b.value
            except GPIOZeroError as exc:
                print(f"Error reading GPIO state: {exc}", file=sys.stderr)
                break

            if state_a != 1 or state_b != 1:
                print(f"State A: {state_a}, State B: {state_b} (expected 1)")
            else:
                print(f"State A: {state_a}, State B: {state_b}")

            time.sleep(POLL_INTERVAL)
    finally:
        for pin in (pin_a, pin_b):
            if pin is not None:
                try:
                    pin.close()
                except Exception:
                    pass


if __name__ == "__main__":
    main()

import serial
import signal
import sys

SERIAL_PORT = '/dev/serial0'  # Raspberry Pi primary UART (GPIO 14/15)
BAUD_RATE = 115200
READ_TIMEOUT = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def exchange_data(ser):
    """Read one line from the serial port and print it, or exit on error."""
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return False

    if not raw:
        print("No data received (timeout).", file=sys.stderr)
        return False

    try:
        line = raw.decode('ascii', errors='replace').strip()
    except Exception as exc:
        print(f"Decode error: {exc}", file=sys.stderr)
        return False

    if not line:
        return False

    print(f"Received: {line}")
    return True

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=READ_TIMEOUT)
        print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud.")

        while _running:
            exchange_data(ser)

    except serial.SerialException as exc:
        print(f"Failed to open serial port: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

