import time
import signal
import sys
from gpiozero import PWMOutputDevice

PWM_PIN_1 = 12
PWM_PIN_2 = 20
PWM_PIN_3 = 21
PWM_FREQUENCY = 0.03

pwm_devices = []

def cleanup(signum=None, frame=None):
    for dev in pwm_devices:
        try:
            dev.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def main():
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        pwm1 = PWMOutputDevice(PWM_PIN_1, frequency=PWM_FREQUENCY)
        pwm2 = PWMOutputDevice(PWM_PIN_2, frequency=PWM_FREQUENCY)
        pwm3 = PWMOutputDevice(PWM_PIN_3, frequency=PWM_FREQUENCY)
        pwm_devices = [pwm1, pwm2, pwm3]
    except Exception as e:
        print(f"Failed to initialize PWM devices: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        while True:
            for dev in pwm_devices:
                dev.value = 0.5
            time.sleep(PWM_FREQUENCY)
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

import time
import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin numbers
LED_PIN = 17
ALERT_PIN = 27
POLL_INTERVAL = 60

# Global handles so the signal handler can release them
_led = None
_alert = None
_running = True


def _cleanup():
    """Release GPIO resources safely."""
    global _led, _alert
    for name, dev in (("led", _led), ("alert", _alert)):
        if dev is not None:
            try:
                dev.close()
            except Exception:
                pass
    _led = _alert = None


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def read_led():
    """Return True if the LED is currently ON, else False."""
    if _led is None:
        return False
    try:
        return bool(_led.value)
    except DeviceClosed:
        return False
    except GPIOZeroError:
        return False


def main():
    global _led, _alert

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize GPIO devices with error handling
    try:
        _led = OutputDevice(LED_PIN)
        _alert = OutputDevice(ALERT_PIN)
    except GPIOZeroError as exc:
        print(f"Error: could not initialize GPIO devices: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error during GPIO init: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    print(f"Monitoring LED on GPIO{LED_PIN} and ALERT on GPIO{ALERT_PIN} "
          f"(polling every {POLL_INTERVAL} s). Press Ctrl+C to exit.")

    try:
        while _running:
            try:
                led_state = read_led()
            except DeviceClosed:
                print("Error: LED device closed unexpectedly.", file=sys.stderr)
                break
            except GPIOZeroError as exc:
                print(f"Error reading LED state: {exc}", file=sys.stderr)
                break

            if led_state:
                print("LED ON")
            else:
                print("LED OFF")

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < POLL_INTERVAL:
                time.sleep(1)
                slept += 1

    finally:
        _cleanup()
        print("GPIO cleanup done. Exiting.")


if __name__ == "__main__":
    main()

