import time
import signal
import sys
import board
import adafruit_dht

# DHT22 data pins (BCM numbering)
DHT_PINS = {4, 5, 17, 23}

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def main():
    global _running

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize DHT22 devices on each configured pin
    devices = []
    for pin in DHT_PINS:
        try:
            dev = adafruit_dht.DHT22(getattr(board, f"D{pin}"))
            devices.append(dev)
        except Exception as e:
            print(f"Error: Failed to initialize DHT22 on GPIO {pin}: {e}", file=sys.stderr)
            sys.exit(1)

    print("DHT22 monitoring started. Press Ctrl+C to stop.")

    try:
        while _running:
            for dev in devices:
                try:
                    temp = dev.temperature
                    hum = dev.humidity

                    if temp is not None and hum is not None:
                        print(f"Temperature: {temp:.1f} C, Humidity: {hum:.1f} %")
                    else:
                        print("Warning: Incomplete reading from DHT22")

                except RuntimeError as e:
                    # DHT22 often has transient read errors; log and continue
                    print(f"Warning: Read error from DHT22: {e}", file=sys.stderr)
                except Exception as e:
                    print(f"Warning: Unexpected error reading DHT22: {e}", file=sys.stderr)

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < 60:
                time.sleep(1)
                slept += 1

    finally:
        # Clean up: release resources and deinitialize sensors
        for dev in devices:
            try:
                dev.exit()
            except Exception:
                pass
        print("DHT22 monitoring stopped. Resources released.")

if __name__ == "__main__":
    main()

