import serial
import time
import sys

SERIAL_PORT = '/dev/serial0'  # Raspberry Pi primary UART (GPIO 14/15)
BAUD_RATE = 115200
READ_INTERVAL = 1.0
VALID_MIN = 0
VALID_MAX = 100


def check_validity(value):
    """Return True if value is within the documented range."""
    return VALID_MIN <= value <= VALID_MAX


def main():
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1.0,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {SERIAL_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    print(f"Listening on {SERIAL_PORT} @ {BAUD_RATE} baud. Press Ctrl+C to stop.")

    try:
        while True:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Serial read error: {exc}", file=sys.stderr)
                break

            if not raw:
                # Timeout with no data — device may be absent or not responding.
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                value = float(line)
            except ValueError:
                print(f"Invalid data (not a float): '{line}'", file=sys.stderr)
                continue

            if check_validity(value):
                print(f"Received: {value}")
            else:
                print(f"Received out of range: {value}", file=sys.stderr)

            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

