import time
import signal
import sys
from smbus2 import SMBus, i2c_msg

PCA9685_ADDR = 0x40
I2C_BUS = 0
READ_INTERVAL_S = 0.15

running = True
bus = None


def handle_signal(signum, frame):
    global running
    running = False


def read_channel(bus, channel):
    """Read a 16-bit value from a PCA9685 channel and validate it."""
    msg_w = i2c_msg.write(PCA9685_ADDR, [0x00, (0x00 | channel) >> 8, (0x00 | channel) & 0xff])
    msg_r = i2c_msg.read(PCA9685_ADDR, 2)
    bus.i2c_rdwr(msg_w, msg_r)
    raw = list(msg_r)
    if len(raw) < 2:
        raise IOError("Short read from PCA9685")
    val = (raw[0] << 8) | raw[1]
    if val & 0x8000:
        val -= 0x10000
    if val < 0 or val > 0xFFFF:
        raise IOError(f"Channel {channel} out of range: {val}")
    return val


def main():
    global bus
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except FileNotFoundError:
        print(f"Error: I2C bus {I2C_BUS} not found. Enable I2C with 'sudo raspi-config'.", file=sys.stderr)
        sys.exit(1)
    except PermissionError:
        print(f"Error: Permission denied on I2C bus {I2C_BUS}. Run as root or add user to 'i2c' group.", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"Error: Cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                val = read_channel(bus, 0)
                print(f"Channel 0: {val}")
            except IOError as e:
                print(f"Error reading PCA9685: {e}", file=sys.stderr)
            time.sleep(READ_INTERVAL_S)
    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass


if __name__ == "__main__":
    main()

