import time
import signal
import sys
from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
TSL2561_ADDR = 0x29

# TSL2561 registers
REG_CONTROL = 0x12
REG_INT_STATUS = 0x13
REG_DATA = 0x16
REG_ID = 0x20

# Control register bits
CTRL_ENABLE = 0x01
CTRL_INTEGRATION_TIME = 0b00000100  # 100ms integration for best linearity
CTRL_GAIN = 0b00000010  # Gain x1

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _write_reg(bus, reg, value):
    bus.write_byte_data(TSL2561_ADDR, reg, value)


def _read_reg(bus, reg):
    return bus.read_byte_data(TSL2561_ADDR, reg)


def _read_data(bus):
    data = _read_reg(bus, REG_DATA)
    return (data << 8) | _read_reg(bus, REG_DATA)


def _read_id(bus):
    return _read_reg(bus, REG_ID)


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    # Verify device ID
    try:
        id = _read_id(bus)
        if id != 0x00:
            print(f"Warning: unexpected TSL2561 ID 0x{id:02X} (expected 0x00)", file=sys.stderr)
    except OSError as e:
        print(f"Warning: cannot read TSL2561 ID: {e}", file=sys.stderr)

    # Enable sensor and set integration time/gain
    try:
        _write_reg(bus, REG_CONTROL, CTRL_ENABLE | CTRL_INTEGRATION_TIME | CTRL_GAIN)
    except OSError as e:
        print(f"Error: cannot write control register: {e}", file=sys.stderr)
        sys.exit(1)

    print("TSL2561 sensor ready. Reading light intensity (lux) every 1 second. Press Ctrl+C to stop.")

    try:
        while _running:
            try:
                raw = _read_data(bus)
                lux = raw / 1.2
                print(f"Light Intensity: {lux:.2f} lux")
            except OSError as e:
                print(f"Warning: I2C read error: {e}", file=sys.stderr)

            time.sleep(1)
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass
        print("\nProgram terminated.")


if __name__ == "__main__":
    main()

import time
import signal
import sys
import board
import adafruit_dht

# DHT22 data pins (BCM numbering)
DHT_PINS = {4, 7, 11, 17}

# Global handle so the signal handler can release it
dht_device = None
running = True


def cleanup():
    """Release the DHT22 device if it was initialised."""
    global dht_device
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
        dht_device = None


def handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global running
    running = False


def main():
    global dht_device

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    # Initialise the DHT22 on the first available pin
    for pin in DHT_PINS:
        try:
            dht_device = adafruit_dht.DHT22(getattr(board, f"D{pin}"))
            break
        except Exception as exc:
            print(f"Warning: could not initialise DHT22 on GPIO {pin}: {exc}", file=sys.stderr)
            dht_device = None

    if dht_device is None:
        print("Error: no DHT22 device found on any of the configured pins.", file=sys.stderr)
        sys.exit(1)

    print("DHT22 reader started. Press Ctrl+C to stop.")

    try:
        while running:
            try:
                temperature = dht_device.temperature
                humidity = dht_device.humidity

                if temperature is None or humidity is None:
                    print("Error: DHT22 returned None for temperature or humidity.", file=sys.stderr)
                else:
                    print(f"Temperature: {temperature:.1f} C  Humidity: {humidity:.1f} %")

            except RuntimeError as exc:
                # Common transient errors (checksum, timeout, etc.)
                print(f"RuntimeError reading DHT22: {exc}", file=sys.stderr)
            except Exception as exc:
                # Unexpected error (device disconnected, bus error, etc.)
                print(f"Unexpected error reading DHT22: {exc}", file=sys.stderr)

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while running and slept < 5:
                time.sleep(0.1)
                slept += 0.1

    finally:
        cleanup()
        print("Program stopped.")


if __name__ == "__main__":
    main()

