import time
import signal
import sys
import board
import busio
from adafruit_mcp3xxx.mcp3008 import MCP3008
from adafruit_mcp3xxx.analog_in import AnalogIn

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def main():
    global _running

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize I2C bus using board.SCL / board.SDA
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    # Initialize MCP3008 on channel 0
    try:
        mcp = MCP3008(i2c, address=0x68)
    except Exception as e:
        print(f"Error initializing MCP3008: {e}", file=sys.stderr)
        sys.exit(1)

    # Create a named AnalogIn object for channel 0
    try:
        channel = AnalogIn(mcp, 0)
    except Exception as e:
        print(f"Error configuring MCP3008 channel 0: {e}", file=sys.stderr)
        sys.exit(1)

    # Sampling loop
    try:
        for i in range(25):
            if not _running:
                break

            try:
                # Read raw 10-bit value (0-1023)
                raw = channel.value
                # Validate reading range
                if 0 <= raw <= 1023:
                    print(f"Reading {i+1}: {raw}")
                else:
                    print(f"Reading {i+1}: Invalid value {raw}", file=sys.stderr)
            except Exception as e:
                print(f"Error reading MCP3008 on channel 0: {e}", file=sys.stderr)
                break

            # Wait before next reading (interruptible)
            time.sleep(0.05)

    except KeyboardInterrupt:
        pass
    finally:
        # Release hardware resources on all exit paths
        try:
            channel.deinit()
        except Exception:
            pass
        try:
            mcp.deinit()
        except Exception:
            pass
        try:
            i2c.deinit()
        except Exception:
            pass
        print("Resources released. Exiting.")

if __name__ == "__main__":
    main()

import time
import signal
import sys
from smbus2 import SMBus, i2c_msg

MPU6050_ADDR = 0x68
I2C_BUS = 0
READ_INTERVAL = 0.1

running = True

def handle_signal(signum, frame):
    global running
    running = False

def read_mpu6050(bus, addr):
    """Read a 16-bit signed value from the MPU6050 and return it, or None on error."""
    try:
        raw = bus.read_word_data(addr, 0x78)
        # smbus2 WordData returns little-endian; convert to signed 16-bit
        val = ((raw << 8) & 0xFF00) | ((raw >> 8) & 0x00FF)
        if val >= 0x8000:
            val -= 0x10000
        return val
    except OSError:
        return None

def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    bus = None
    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        # Probe the device address to confirm it is present
        try:
            bus.read_byte_data(MPU6050_ADDR, 0x75)
        except OSError:
            print(f"Error: no MPU6050 found at address 0x{MPU6050_ADDR:02X} on bus {I2C_BUS}", file=sys.stderr)
            sys.exit(1)

        for i in range(3):
            if not running:
                break
            val = read_mpu6050(bus, MPU6050_ADDR)
            if val is None:
                print(f"Error: failed to read MPU6050 (device absent or bus error)", file=sys.stderr)
                break
            print(f"Reading {i+1}: {val}")
            time.sleep(READ_INTERVAL)

    finally:
        if bus is not None:
            bus.close()

