import time
import signal
import sys
from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
TCS34725_ADDR = 0x29
READ_INTERVAL_S = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _write_cmd(bus, cmd):
    msg = i2c_msg.write(TCS34725_ADDR, [cmd])
    bus.i2c_rdwr(msg)


def _read_data(bus):
    write_msg = i2c_msg.write(TCS34725_ADDR, [0x00])
    read_msg = i2c_msg.read(TCS34725_ADDR, 6)
    bus.i2c_rdwr(write_msg, read_msg)
    return list(read_msg)


def _validate_reading(raw):
    if len(raw) < 6:
        raise ValueError(f"short read: {raw}")
    if raw[0] & 0x80:
        raise ValueError("device reset mid-read")
    return {
        "red": raw[1] | (raw[2] << 8),
        "green": raw[3] | (raw[4] << 8),
        "blue": raw[5] | (raw[6] << 8),
    }


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        _write_cmd(bus, 0x01)  # power on
        time.sleep(0.1)
        while _running:
            try:
                raw = _read_data(bus)
            except OSError as exc:
                print(f"Error: I2C read failed: {exc}", file=sys.stderr)
                break

            try:
                data = _validate_reading(raw)
            except ValueError as exc:
                print(f"Error: invalid reading: {exc}", file=sys.stderr)
                continue

            print(f"Red: {data['red']}, Green: {data['green']}, Blue: {data['blue']}")
            time.sleep(READ_INTERVAL_S)
    finally:
        if bus is not None:
            try:
                _write_cmd(bus, 0x00)  # power off
            except OSError:
                pass
            bus.close()


if __name__ == "__main__":
    main()

import time
import signal
import sys
from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
I2C_ADDR = 0x40
READ_INTERVAL_S = 1.0
NUM_READINGS = 60

running = True

def _handle_signal(signum, frame):
    global running
    running = False

def read_ina219(bus, addr):
    """Read voltage, current, power from INA219 and return a dict."""
    write_msg = i2c_msg.write(addr, [0x01])
    read_msg = i2c_msg.read(addr, 3)
    bus.i2c_rdwr(write_msg, read_msg)
    raw = list(read_msg)
    if len(raw) < 3:
        raise IOError("INA219 short read")
    return {
        'voltage': (raw[0] << 8) | raw[1],
        'current': (raw[2] << 8) | raw[1],
        'power': (raw[2] << 8) | raw[1],
    }

def main():
    global running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        # Probe the device address
        try:
            bus.read_byte(I2C_ADDR)
        except OSError:
            print(f"Error: no device found at I2C address 0x{I2C_ADDR:02X}", file=sys.stderr)
            sys.exit(1)

        for i in range(NUM_READINGS):
            if not running:
                break
            try:
                data = read_ina219(bus, I2C_ADDR)
                print(f"Reading {i + 1}/{NUM_READINGS} - "
                      f"Voltage: {data['voltage']} mV, Current: "
                      f"{data['current']} mA, Power: {data['power']} mW")
            except OSError as e:
                print(f"Error reading INA219 (reading {i + 1}/{NUM_READINGS}): {e}", file=sys.stderr)
            except Exception as e:
                print(f"Unexpected error reading INA219 (reading {i + 1}/{NUM_READINGS}): {e}", file=sys.stderr)

            if i < NUM_READINGS - 1 and running:
                time.sleep(READ_INTERVAL_S)

        if running:
            print("Completed all readings.")
        else:
            print("Interrupted by signal.")

    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass

if __name__ == "__main__":
    main()

