    sys.exit(1)

# ADS1115 I2C address (default 0x48)
ADS1115_ADDRESS = 0x48

# Global resources for cleanup
_i2c = None
_ads = None
_running = True


def _cleanup():
    """Release hardware resources."""
    global _i2c, _ads
    if _ads is not None:
        try:
            _ads.gain = None
        except Exception:
            pass
        try:
            _ads = None
        except Exception:
            pass
    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass
        _i2c = None


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def main():
    global _i2c, _ads

    # Register signal handlers for graceful exit
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize I2C bus (default SCL=GPIO3, SDA=GPIO2 on board)
    try:
        _i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Failed to initialize I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    # Initialize ADS1115 at address 0x48
    try:
        _ads = ADS1115(_i2c, address=ADS1115_ADDRESS)
        _ads.gain = 1  # +/-4.096V range
    except Exception as e:
        print(f"Failed to initialize ADS1115 at 0x{ADS1115_ADDRESS:02X}: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # Create AnalogIn on channel 0 (single-ended AIN0)
    try:
        _chan = AnalogIn(_ads, 0)
    except Exception as e:
        print(f"Failed to configure channel 0: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # Main sampling loop
    try:
        while _running:
            try:
                voltage = _chan.voltage
                print(f"ADC Channel 0: {voltage:.4f} V")
            except Exception as e:
                print(f"Read error: {e}", file=sys.stderr)
            time.sleep(0.1)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

