import time
import signal
import sys
from smbus2 import SMBus, i2c_msg

BME280_I2C_ADDR = 0x76
BME280_REG_ID = 0xD0
BME280_REG_RESET = 0xE0
BME280_REG_CTRL_HUM = 0xF2
BME280_REG_STATUS = 0xF3
BME280_REG_CTRL_MEAS = 0xF4
BME280_REG_DATA = 0xF7

BME280_ID = b'BME280'

running = True


def signal_handler(signum, frame):
    global running
    running = False


def bme280_init(bus):
    try:
        chip_id = bus.read_byte_data(BME280_I2C_ADDR, BME280_REG_ID)
    except OSError:
        raise RuntimeError(f"No BME280 found at 0x{BME280_I2C_ADDR:02X}")
    if chip_id != BME280_ID:
        raise RuntimeError(f"Unexpected chip ID 0x{chip_id:02X}, expected 0x{BME280_ID:02X}")
    try:
        bus.write_byte_data(BME280_I2C_ADDR, BME280_REG_RESET, 0xB6)
        time.sleep(0.01)
    except OSError:
        raise RuntimeError("BME280 reset failed")
    ctrl_hum = bus.read_byte_data(BME280_I2C_ADDR, BME280_REG_CTRL_HUM)
    ctrl_meas = bus.read_byte_data(BME280_I2C_ADDR, BME280_REG_CTRL_MEAS)
    if (ctrl_hum & 0x01) or (ctrl_meas & 0x01):
        raise RuntimeError("BME280 not in sleep mode")
    return ctrl_hum, ctrl_meas


def read_bme280(bus):
    try:
        data = bus.read_i2c_block_data(BME280_I2C_ADDR, BME280_REG_DATA, 8)
    except OSError:
        return None
    raw = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
    if raw & 0x800000:
        raw -= 1 << 32
    if raw & 0x200000:
        raw -= 1 << 18
    if raw & 0x100000:
        raw -= 1 << 16
    if raw & 0x080000:
        raw -= 1 << 14
    if raw & 0x040000:
        raw -= 1 << 12
    if raw & 0x020000:
        raw -= 1 << 10
    if raw & 0x010000:
        raw -= 1 << 8
    if raw & 0x002000:
        raw -= 1 << 6
    if raw & 0x001000:
        raw -= 1 << 4
    if raw & 0x000800:
        raw -= 1 << 2
    if raw & 0x000400:
        raw -= 1 << 0
    return raw


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)
    try:
        ctrl_hum, ctrl_meas = bme280_init(bus)
        print("BME280 initialized at 0x76")
        while running:
            raw = read_bme280(bus)
            if raw is None:
                print("Warning: I2C read error, retrying...", file=sys.stderr)
            else:
                print(f"Temperature: {raw >> 3:5.1f} C")
                print(f"Pressure: {raw & 0x1FFF:5.1f} hPa")
                print(f"Humidity: {raw >> 13:5.1f} %")
                print("-" * 40)
            for _ in range(60):
                if not running:
                    break
                time.sleep(1)
    finally:
        bus.close()
        print("I2C bus closed. Exiting.")


if __name__ == "__main__":
    main()

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

BME680_I2C_ADDR = 0x77
BME680_REG_CTRL_HUM = 0x1A
BME680_REG_CTRL_MEAS = 0x1B
BME680_REG_DATA = 0x1E
BME680_REG_CALIB = 0x17

running = True


def _signal_handler(signum, frame):
    global running
    running = False


def _write_reg(bus, reg, value):
    bus.write_byte_data(BME680_I2C_ADDR, reg, value)


def _read_reg(bus, reg):
    return bus.read_byte_data(BME680_I2C_ADDR, reg)


def _read_block(bus, reg, length):
    return bus.read_i2c_block_data(BME680_I2C_ADDR, reg, length)


def _init_bme680(bus):
    _write_reg(bus, BME680_REG_CTRL_HUM, 0x00)
    _write_reg(bus, BME680_REG_CTRL_MEAS, 0x01)
    _write_reg(bus, BME680_REG_CALIB, 0x00)


def _read_raw_data(bus):
    data = _read_block(bus, BME680_REG_DATA, 8)
    raw = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
    if raw & 0x8000:
        raw -= 1 << 16
    return raw


def main():
    global running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Error: cannot open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        _init_bme680(bus)
    except OSError as e:
        print(f"Error: BME680 not found at 0x{BME680_I2C_ADDR:02X}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                raw = _read_raw_data(bus)
            except OSError as e:
                print(f"Error: I2C read failed: {e}", file=sys.stderr)
                time.sleep(1)
                continue

            if raw & 0x8000:
                print("Warning: raw data saturated, skipping", file=sys.stderr)
                time.sleep(1)
