    for dev in _outputs:
        try:
            dev.close()
        except Exception:
            pass
    _outputs.clear()
    if signum is not None:
        sys.exit(0)


def read_gpio_state(pin):
    """Read the current state of a GPIO pin.

    Returns the integer value (0 or 1) of the pin, or None on error.
    """
    try:
