import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIODeviceError, GPIODeviceClosed

# BCM pin numbers
PINS = [5, 6, 20, 21]

# Global list so the signal handler can clean up
_devices = []
_running = True


def _cleanup():
    """Close every device so the GPIO line is released."""
    for dev in _devices:
        try:
            dev.close()
        except GPIODeviceClosed:
            pass
        except Exception:
            pass
    _devices.clear()


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM by exiting cleanly."""
    global _running
    _running = False
    _cleanup()
    sys.exit(0)


def read_gpio(pin):
    """Read the current state of a gpiozero OutputDevice.

    Returns the integer value (0 or 1) the pin is currently driving.
    Returns None if the device is not open or the reading fails.
    """
    if pin not in _devices:
        return None
    try:
        return int(pin.value)
    except (GPIODeviceClosed, Exception):
        return None


def main():
    global _devices

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize OutputDevice objects (active_high=True means default=1)
    for p in PINS:
        try:
            dev = OutputDevice(p, active_high=True, initial_value=True)
            _devices.append(dev)
        except GPIODeviceError as exc:
            print(f"Error: failed to initialize GPIO {p}: {exc}", file=sys.stderr)
            _cleanup()
            sys.exit(1)

    try:
        for p in PINS:
            state = read_gpio(p)
            if state is None:
                print(f"Error: failed to read GPIO {p}", file=sys.stderr)
                break
            print(f"GPIO {p} = {state}")
    except Exception as exc:
        print(f"Error: unexpected failure reading GPIO pins: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

