import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'  # Raspberry Pi primary UART (GPIO 14/15)
BAUD_RATE = 115200
READ_INTERVAL = 0.1  # seconds

running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_serial_data(ser):
    """Read one line from the serial port and return it as a string, or None on error."""
    try:
        raw = ser.readline()
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None

def check_validity(data):
    """Return True if data is a non-empty, non-zero integer."""
    try:
        value = int(data)
        return value != 0
    except ValueError:
        return False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud. Reading data...")

        while running:
            data = read_serial_data(ser)
            if data is None:
                # Device may have disconnected mid-read; give up for this cycle.
                time.sleep(READ_INTERVAL)
                continue

            if check_validity(data):
                print(f"Received: {data}")
            else:
                print(f"Invalid data received: {data}", file=sys.stderr)

            time.sleep(READ_INTERVAL)

    except serial.SerialException as e:
        print(f"Error opening serial port: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

