import time
import signal
import sys
from gpiozero import DigitalOutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# HC-SR04 GPIO pins (BCM numbering)
ECHO_PIN = 19
TRIG_PIN = 20
SOUND_SPEED_CM_S = 34300.0
TIMEOUT_S = 0.5
POLL_INTERVAL_S = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def measure_distance(trig, echo):
    """Trigger a 10us pulse and time the echo pulse. Returns distance in cm, or None on timeout."""
    trig.off()
    time.sleep(0.000002)  # 2us settle
    trig.on()
    time.sleep(0.00001)  # 10us pulse
    trig.off()

    deadline = time.monotonic() + TIMEOUT_S
    while echo.value == 0:
        if time.monotonic() > deadline:
            return None
    pulse_start = time.monotonic()

    deadline = time.monotonic() + TIMEOUT_S
    while echo.value == 1:
        if time.monotonic() > deadline:
            return None
    pulse_end = time.monotonic()

    pulse_duration = pulse_end - pulse_start
    distance = (pulse_duration * SOUND_SPEED_CM_S) / 2.0
    return round(distance, 2)

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        trig = DigitalOutputDevice(TRIG_PIN)
        echo = DigitalOutputDevice(ECHO_PIN)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO pins: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            dist = measure_distance(trig, echo)
            if dist is not None:
                print(f"Measured Distance = {dist} cm")
            else:
                print("No echo received (object out of range or sensor not responding).")
            time.sleep(POLL_INTERVAL_S)
    finally:
        try:
            echo.close()
            trig.close()
        except DeviceClosed:
            pass
        print("GPIO cleanup done.")

if __name__ == "__main__":
    main()

