import sys
from smbus2 import SMBus

MPU6050_ADDR = 0x68
I2C_BUS = 0
READ_INTERVAL = 0.1
NUM_READINGS = 8

running = True

def handle_signal(signum, frame):
    global running
    running = False

def read_mpu6050(bus):
    try:
        # Read 14 bytes starting at WHO_AM_I (0x75)
        data = bus.read_i2c_block_data(MPU6050_ADDR, 0x75, 14)
        # Verify WHO_AM_I matches (0x68)
        if data[0] != 0x68:
            raise RuntimeError(f"WHO_AM_I mismatch: got 0x{data[0]:02X}, expected 0x68")
        # Check DLPF bit (bit 3 of WHO_AM_I)
