import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

PIN_A = 17
PIN_B = 18
POLL_INTERVAL = 0.2

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    pin_a = None
    pin_b = None
    try:
        pin_a = OutputDevice(PIN_A)
        pin_b = OutputDevice(PIN_B)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO pins: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                state_a = pin_a.value
                state_b = pin_b.value
            except GPIOZeroError as exc:
                print(f"Error reading GPIO state: {exc}", file=sys.stderr)
                break

            if state_a != 1 or state_b != 1:
                print("Invalid state: A=0, B=0", file=sys.stderr)
            else:
                print(f"State A={state_a}, State B={state_b}")

            time.sleep(POLL_INTERVAL)
    finally:
        for pin in (pin_a, pin_b):
            if pin is not None:
                try:
                    pin.close()
                except Exception:
                    pass


if __name__ == "__main__":
    main()

import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/serial0'  # Raspberry Pi primary UART (GPIO 14/15)
BAUD_RATE = 115200
READ_INTERVAL = 2.0
NUM_READINGS = 3

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def exchange_data(ser):
    """Read one line from the serial port and print it."""
    try:
        raw = ser.readline()
        if raw:
            print(raw.decode('ascii', errors='replace').strip())
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud")

        for i in range(NUM_READINGS):
            if not _running:
                print("Interrupted by user.")
                break
            exchange_data(ser)
            if i < NUM_READINGS - 1:
                time.sleep(READ_INTERVAL)

        if _running:
            print("Data exchange complete.")

    except serial.SerialException as e:
        print(f"Error: Could not open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

import time
import sys
import signal
import smbus2

I2C_BUS = 1
TSL2591_ADDR = 0x29
READ_INTERVAL = 10

running = True

def handle_signal(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)

def read_tsl2591(bus):
    try:
        data = bus.read_i2c_block_data(TSL2591_ADDR, 0x00, 6)
    except OSError as e:
        print(f"I2C read error: {e}", file=sys.stderr)
        return None

    if len(data) < 6:
        print("Short read from TSL2591", file=sys.stderr)
        return None

    raw_ir = (data[0] << 8) | data[1]
    raw_vl = (data[2] << 8) | data[3]
    raw_infrared = (data[4] << 8) | data[5]

    if raw_ir == 0:
        print("TSL2591 returned zero IR", file=sys.stderr)
        return None

    return raw_ir, raw_vl, raw_infrared

def main():
    global running
    bus = None
    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(3):
            if not running:
                break
            result = read_tsl2591(bus)
            if result is None:
                print("Reading {0}: invalid data".format(i + 1))
            else:
                ir, vl, iri = result
                print("Reading {0}: IR={ir} VL={vl} IRI={iri}".format(i + 1))
            if i < 2 and running:
                time.sleep(READ_INTERVAL)
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass

if __name__ == "__main__":
    main()

import time
import signal
import sys
import board
import adafruit_dht

# Global sensor handle so the signal handler can clean up
_sensor = None

def cleanup():
    """Release the DHT22 sensor if it was initialized."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None

def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM by cleaning up and exiting."""
    print(f"\nReceived signal {signum}, exiting...")
    cleanup()
    sys.exit(0)

def main():
    global _sensor

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize the DHT22 on GPIO 4 (BCM) using adafruit-circuitpython-dht
    try:
        _sensor = adafruit_dht.DHT22(board.D4, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT22 on GPIO 4: {e}")
        sys.exit(1)

    try:
        for cycle in range(3):
            try:
                temperature = _sensor.temperature
                humidity = _sensor.humidity

                if temperature is not None and humidity is not None:
                    print(f"Cycle {cycle + 1}: Temp = {temperature:.1f} C, Humidity = {humidity:.1f} %")
                else:
                    print(f"Cycle {cycle + 1}: Sensor returned None (check wiring or pull-up)")

            except RuntimeError as e:
                # DHT22 can occasionally fail to read; log and continue
                print(f"Cycle {cycle + 1}: Read error - {e}")

            time.sleep(60)

    finally:
        cleanup()

if __name__ == "__main__":
    main()

import signal
import sys
import time
from smbus2 import SMBus, i2c_msg

BME280_I2C_ADDR = 0x76
BME280_REG_ID = 0xD0
BME280_CHIP_ID = 0x60

running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_bme280_id(bus):
    try:
        msg = i2c_msg.read(BME280_I2C_ADDR, 1)
        bus.i2c_rdwr(msg)
        return list(msg)[0]
    except OSError:
        return None

def read_bme280_data(bus):
    try:
        data = bus.read_i2c_block_data(BME280_I2C_ADDR, 0xF7, 8)
        raw = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
        temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4)
        pres = (data[6] << 12) | (data[7] << 4) | (data[8] >> 4)
        return raw, temp, pres
    except OSError:
        return None, None, None

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = None
    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Failed to open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        chip_id = read_bme280_id(bus)
        if chip_id != BME280_CHIP_ID:
            print(f"Invalid BME280 ID: 0x{chip_id:02X} (expected 0x{BME280_CHIP_ID:02X})", file=sys.stderr)
            sys.exit(1)

        while running:
            result = read_bme280_data(bus)
            if result is None:
                print("Error reading BME280 data (I2C bus error).", file=sys.stderr)
            else:
                raw, temp, pres = result
                print(f"Raw: {raw}, Temp: {temp} mS, Pressure: {pres} hPa")
            time.sleep(1.0)
    finally:
        if bus is not None:
            bus.close()

if __name__ == "__main__":
    main()

import time
import signal
import sys
import board
import adafruit_dht

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def main():
    global _running

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize DHT22 on GPIO 4 (BCM) using adafruit-circuitpython-dht
    # board.D4 maps to BCM GPIO 4
    try:
        dht_device = adafruit_dht.DHT22(board.D4, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT22 on GPIO 4: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        # Perform 3 readings
        for cycle in range(3):
            if not _running:
                break

            try:
                temperature = dht_device.temperature
                humidity = dht_device.humidity

                if temperature is not None and humidity is not None:
                    print(f"Cycle {cycle + 1}: Temp = {temperature:.1f} C, Humidity = {humidity:.1f} %")
                else:
                    print(f"Cycle {cycle + 1}: Read failed (None values)")

            except RuntimeError as e:
                # DHT22 can be flaky; retry on next cycle
                print(f"Cycle {cycle + 1}: Read error: {e}", file=sys.stderr)

            # Wait before next reading (skip on interrupt)
            if _running:
                time.sleep(2.0)

    finally:
        # Release the DHT22 device (stops the underlying GPIO/PWM bus)
        try:
            dht_device.exit()
        except Exception:
            pass

if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

OUTPUT_PIN = 17
POLL_INTERVAL = 5.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        output = OutputDevice(OUTPUT_PIN)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                output.on()
                print("GPIO 17 -> HIGH")
            except GPIOZeroError as exc:
                print(f"Error writing HIGH to GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr)
                break

            if not _running:
                break

            time.sleep(POLL_INTERVAL)

            try:
                output.off()
                print("GPIO 17 -> LOW")
            except GPIOZeroError as exc:
                print(f"Error writing LOW to GPIO {OUTPUT_PIN}: {exc}", file=sys.stderr)
                break

            if not _running:
                break

            time.sleep(POLL_INTERVAL)
    finally:
        try:
            output.close()
        except Exception:
            pass
        print("GPIO cleanup done.")

if __name__ == "__main__":
    main()
